with sync_playwright() as p:
 b=p.chromium.launch();page=b.new_page(viewport={'width':1280,'height':800});page.goto('http://localhost:5311/art/ruta-native-painted-sprites-v2/packing/head-pivot-trial/review.html');page.wait_for_function('window.reviewState?.ready');r=page.evaluate('''async()=>{const m=await(await fetch('manifest.json')).json(),im=new Image();im.src=m.paintedAtlas.path;await im.decode();const rect=m.frames[0].paintedRect,S=m.fixedScale,out=[];const panel=document.createElement('div');panel.style='position:fixed;inset:0;background:#ece2ce;z-index:99999;display:flex;flex-wrap:wrap';document.body.append(panel);for(const kind of ['two-pass','single-pass'])for(const frac of [0,.25,.5,.75]){const small=document.createElement('canvas');small.width=256;small.height=320;const c=document.createElement('canvas');c.width=320;c.height=400;const ctx=c.getContext('2d');if(kind==='two-pass'){small.getContext('2d').drawImage(im,...rect,29+frac,59+frac,162*S,200*S);ctx.drawImage(small,0,0,320,400)}else ctx.drawImage(im,...rect,(29+frac)*1.25,(59+frac)*1.25,162*S*1.25,200*S*1.25);const d=ctx.getImageData(0,0,320,400).data;let n=0,g=0;for(let y=1;y<399;y++)for(let x=1;x<319;x++){const k=(y*320+x)*4;if(d[k+3]<240||d[k+7]<240||d[k+1283]<240)continue;for(let ch=0;ch<3;ch++){g+=(d[k+ch]-d[k+4+ch])**2+(d[k+ch]-d[k+1280+ch])**2;n+=2}}out.push({kind,frac,interiorGradientEnergy:g/n,samples:n});const box=document.createElement('div');box.style='width:25%;font:14px sans-serif';box.append(kind+' offset '+frac,c);c.style='width:256px;height:320px';panel.append(box)}return {frame:0,sourceRect:rect,scale:S,results:out}}''');page.screenshot(path=str(O/'same-frame-comparison.png'));(O/'same-frame.json').write_text(json.dumps(r,indent=2)+'\n');b.close()
